import json
import itertools

# Input data
n_weeks = 4
n_groups = 3
group_size = 3

n_golfers = n_groups * group_size

model = cp_model.CpModel()

# assign[w][g][s]: golfer assigned to slot s in group g in week w
assign = {}
for w in range(n_weeks):
    for g in range(n_groups):
        for s in range(group_size):
            assign[(w, g, s)] = model.NewIntVar(0, n_golfers - 1, f'assign_w{w}_g{g}_s{s}')

# 1. Each group in each week has unique golfers (no duplicates in a group)
for w in range(n_weeks):
    for g in range(n_groups):
        model.AddAllDifferent([assign[(w, g, s)] for s in range(group_size)])

# 2. Each golfer plays exactly once per week
for w in range(n_weeks):
    all_golfers_in_week = [assign[(w, g, s)] for g in range(n_groups) for s in range(group_size)]
    model.AddAllDifferent(all_golfers_in_week)

# 3. No pair of golfers plays together more than once
# For each pair of golfers, count the number of times they are in the same group
pair_played_together = {}
for i in range(n_golfers):
    for j in range(i + 1, n_golfers):
        pair_played_together[(i, j)] = []

        for w in range(n_weeks):
            for g in range(n_groups):
                # If both i and j are in group g in week w
                bools = []
                for s1 in range(group_size):
                    for s2 in range(group_size):
                        if s1 != s2:
                            b1 = model.NewBoolVar(f'is_{i}_w{w}_g{g}_s{s1}')
                            b2 = model.NewBoolVar(f'is_{j}_w{w}_g{g}_s{s2}')
                            model.Add(assign[(w, g, s1)] == i).OnlyEnforceIf(b1)
                            model.Add(assign[(w, g, s1)] != i).OnlyEnforceIf(b1.Not())
                            model.Add(assign[(w, g, s2)] == j).OnlyEnforceIf(b2)
                            model.Add(assign[(w, g, s2)] != j).OnlyEnforceIf(b2.Not())
                            both = model.NewBoolVar(f'both_{i}_{j}_w{w}_g{g}_s{s1}_{s2}')
                            model.AddBoolAnd([b1, b2]).OnlyEnforceIf(both)
                            model.AddBoolOr([b1.Not(), b2.Not()]).OnlyEnforceIf(both.Not())
                            bools.append(both)
                # If any such pair exists, then i and j are together in this group this week
                together = model.NewBoolVar(f'together_{i}_{j}_w{w}_g{g}')
                if bools:
                    model.AddMaxEquality(together, bools)
                else:
                    model.Add(together == 0)
                pair_played_together[(i, j)].append(together)

        # Each pair can play together at most once
        model.Add(sum(pair_played_together[(i, j)]) <= 1)

# Symmetry breaking: order golfers in first group of first week
for s in range(group_size - 1):
    model.Add(assign[(0, 0, s)] < assign[(0, 0, s + 1)])

# Solve
solver = cp_model.CpSolver()
solver.parameters.max_time_in_seconds = 60.0
status = solver.Solve(model)

if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    result = []
    for w in range(n_weeks):
        week = []
        for g in range(n_groups):
            group = []
            for s in range(group_size):
                group.append(solver.Value(assign[(w, g, s)]))
            week.append(group)
        result.append(week)
    solution = {
        'assign': result
    }
    print(json.dumps(solution, indent=4))
