from ortools.sat.python import cp_model
import json

# Input data
n_boats = 5
n_periods = 4
capacity = [6, 8, 12, 12, 12]
crew_size = [2, 2, 2, 2, 4]

model = cp_model.CpModel()

# Variables
is_host = [model.NewBoolVar(f'is_host[{i}]') for i in range(n_boats)]

# visits[g][h][t] = 1 if guest boat g visits host h at period t
visits = {}
for g in range(n_boats):
    for h in range(n_boats):
        for t in range(n_periods):
            visits[g, h, t] = model.NewBoolVar(f'visits[{g},{h},{t}]')

# 1. Host boats: If a boat is a host, its own crew stays on board, and it does not visit anyone.
for b in range(n_boats):
    for t in range(n_periods):
        # Host cannot visit anyone
        for h in range(n_boats):
            model.Add(visits[b, h, t] == 0).OnlyEnforceIf(is_host[b])
        # Non-host must visit exactly one host per period
        model.Add(sum(visits[b, h, t] for h in range(n_boats)) == 1).OnlyEnforceIf(is_host[b].Not())
        # Non-host cannot visit itself
        model.Add(visits[b, b, t] == 0)

# 2. A guest cannot visit the same host more than once
for g in range(n_boats):
    for h in range(n_boats):
        if g != h:
            model.Add(sum(visits[g, h, t] for t in range(n_periods)) <= 1)

# 3. A guest cannot visit a non-host
for g in range(n_boats):
    for h in range(n_boats):
        for t in range(n_periods):
            model.Add(visits[g, h, t] <= is_host[h])

# 4. Capacity constraints: For each host h at period t, sum of all crews on board <= capacity
for h in range(n_boats):
    for t in range(n_periods):
        # Host's own crew is always on board if host
        guests_here = []
        for g in range(n_boats):
            if g != h:
                guests_here.append(visits[g, h, t] * crew_size[g])
        # Only count if h is a host
        model.Add(
            crew_size[h] + sum(guests_here) <= capacity[h]
        ).OnlyEnforceIf(is_host[h])
        # If not a host, no one is on board
        model.Add(sum(visits[g, h, t] for g in range(n_boats) if g != h) == 0).OnlyEnforceIf(is_host[h].Not())

# 5. Guest crews cannot meet more than once
for g1 in range(n_boats):
    for g2 in range(g1 + 1, n_boats):
        meet_times = []
        for h in range(n_boats):
            for t in range(n_periods):
                # Both g1 and g2 visit h at t
                meet = model.NewBoolVar(f'meet_{g1}_{g2}_at_{h}_{t}')
                model.AddBoolAnd([visits[g1, h, t], visits[g2, h, t]]).OnlyEnforceIf(meet)
                model.AddBoolOr([visits[g1, h, t].Not(), visits[g2, h, t].Not()]).OnlyEnforceIf(meet.Not())
                meet_times.append(meet)
        model.Add(sum(meet_times) <= 1)

# 6. A boat cannot visit itself
for b in range(n_boats):
    for t in range(n_periods):
        model.Add(visits[b, b, t] == 0)

# Objective: Minimize the number of hosts
model.Minimize(sum(is_host))

# Solve
solver = cp_model.CpSolver()
solver.parameters.max_time_in_seconds = 60.0
status = solver.Solve(model)

if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    visits_sol = []
    for g in range(n_boats):
        for h in range(n_boats):
            for t in range(n_periods):
                if solver.Value(visits[g, h, t]):
                    visits_sol.append({'guest': g, 'host': h, 'period': t})
    is_host_sol = [solver.Value(is_host[i]) for i in range(n_boats)]
    solution = {
        'visits': visits_sol,
        'is_host': is_host_sol
    }
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
